// 예상 밖 오류를 원문 비밀 없이 state.fail/DLQ 계약으로 정규화한다.
// scope가 없거나 실행 참조가 불완전하면 외부 저장을 호출하지 않는다.
const input = $json;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const safeLabel = (value, fallback) => {
  if (typeof value !== 'string') return fallback;
  const cleaned = value.replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim();
  return cleaned.length > 0 ? cleaned.slice(0, 128) : fallback;
};
// n8n 기본 설정은 Code 노드의 $env 접근을 막아 읽는 순간 예외가 난다. 예외는 무시하고 가져올 때 치환하는 값을 쓴다.
const readEnvScope = () => { try { return typeof $env !== 'undefined' && typeof $env.DUBAKWI_SCOPE === 'string' ? $env.DUBAKWI_SCOPE.trim() : ''; } catch (error) { return ''; } };
const importedScope = '__DUBAKWI_SCOPE__';
const envScope = readEnvScope() || (importedScope !== '__DUBAKWI_SCOPE__' && /^[A-Za-z0-9:_.-]+$/.test(importedScope) ? importedScope : '');
const execution = isObj(input) && isObj(input.execution) ? input.execution : {};
const workflow = isObj(input) && isObj(input.workflow) ? input.workflow : {};
const nodeFromError = isObj(execution.error) && isObj(execution.error.node) ? execution.error.node.name : null;
const failedNode = safeLabel(execution.lastNodeExecuted ?? nodeFromError, 'unknown');
const executionId = typeof execution.id === 'string' && execution.id.trim().length > 0 ? execution.id.trim() : null;
const hasWorkflowRef = (typeof workflow.id === 'string' && workflow.id.trim().length > 0) || (typeof workflow.name === 'string' && workflow.name.trim().length > 0);
const canRecord = envScope.length > 0 && executionId !== null && hasWorkflowRef && failedNode !== 'unknown';
const recovery = {
  version: 1, mode: 'manual_required', action: 'inspect_only', args: null, reference: null,
  reason: canRecord ? '예상 밖 중단: 원 실행과 외부 효과를 운영자가 확인해야 함' : '설정 또는 실행 참조 부족: 자동 복구 금지'
};
return [{ json: {
  op: 'fail', scope: envScope.length > 0 ? envScope : null, execution_id: executionId,
  args: {status: 'unknown', current_step: failedNode, error_code: 'workflow_runtime_error'},
  state_ref: null, recovery, ctx: null, failed_node_id: failedNode,
  error_code: 'workflow_runtime_error', known_ticket_id: null,
  effect: canRecord ? 'unknown' : 'none', effect_plan: canRecord ? 'dlq_alert' : 'none',
  storage_ready: canRecord
} }];

const safe = $('E02 오류 가림과 안전 차단').item.json;
const effect = (status, errorCode = null) => ({status, error_code: errorCode});
return [{json:{
  op:'put', scope:safe.scope, request_id:null, case_id:null, jira_issue_id:null, jira_issue_key:null,
  failed_step:safe.failed_node_id, error_code:safe.error_code, summary:'예상 밖 워크플로우 중단', attempts:0,
  effects:{created_or_reused:effect(safe.effect),context_saved:effect('none'),closed:effect('none'),assigned:effect('none'),alert:effect('none','alert_backend_unconfigured')},
  recovery:safe.recovery, last_execution_id:safe.execution_id
}}];

const safe = $('E02 오류 가림과 안전 차단').item.json;
const dlq = $json;
const stored = dlq && dlq.ok === true;
return [{json:{ok:false,skipped:false,state_ref:null,dlq_id:stored ? (dlq.dlq_id ?? null) : null,error_code:stored ? 'workflow_runtime_error' : 'error_storage_failed',execution_id:safe.execution_id}}];
